import { prisma } from '@/lib/prisma';

// 1. findUnique: TypeScript ONLY allows unique fields in 'where'
const userByEmail = await prisma.user.findUnique({
  where: { email: 'sarah@example.com' },
});

// 2. findFirst: Allows any arbitrary filters with ordering
const latestActiveUser = await prisma.user.findFirst({
  where: { 
    role: 'ADMIN',
    isActive: true 
  },
  orderBy: { createdAt: 'desc' },
});
